create table agency_finance_accounts(id text primary key,tenant_id text not null,package_id text not null,kind text not null check(kind in ('receivable','cost')),category text not null,currency text not null,budget numeric(24,2),requested numeric(24,2) not null check(requested>=0),approved numeric(24,2),status text not null default 'draft' check(status in ('draft','reviewing','approved','rejected')),version bigint not null default 1,snapshot_json jsonb not null,frozen_hash text not null,workflow_id text,created_by text not null,created_at timestamptz not null default now(),unique(tenant_id,id));
create table agency_finance_entries(id text primary key,tenant_id text not null,package_id text not null,account_id text not null,kind text not null check(kind in ('receipt','refund','invoice','invoice_void','waiver','increase','incurred','paid','payment_refund')),amount numeric(24,2) not null check(amount>0),occurred_at timestamptz not null,evidence_version_id text not null,evidence_hash text not null,snapshot_json jsonb not null,frozen_hash text not null,status text not null check(status in ('reviewing','approved','rejected')),version bigint not null default 1,workflow_id text,created_by text not null,created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,account_id) references agency_finance_accounts(tenant_id,id));
create unique index agency_finance_proof_once on agency_finance_entries(tenant_id,package_id,kind,evidence_hash) where status in ('reviewing','approved');
create table agency_completion_states(tenant_id text not null,package_id text not null,version bigint not null default 1,business_note text not null default '',financial_note text not null default '',archive_note text not null default '',retention_years int not null default 10 check(retention_years between 1 and 100),updated_by text not null,updated_at timestamptz not null default now(),primary key(tenant_id,package_id),foreign key(tenant_id,package_id) references agency_packages(tenant_id,id));
